def build_input_test(sentences ,word2index):
    X =[]
    for tokens in sentences:
        curx = [word2index['_pad_']]
        for token in tokens:
            if token in word2index:
                curx.append(word2index[token])
            else:
                curx.append(1)
        X.append(torch.tensor(curx))
    return X

class sentimentdata(Dataset):
    def __init__(self , X,Y, padsz = 40):
        self.X = X
        self.Y = Y
        self.padsz = padsz
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        x = self.X[index]
        y= self.Y[index]
        x_len = len(x)

        if x_len <= self.padsz:
            padded_x = torch.zeros(self.padsz)
            padded_x[:x_len] = x
        else:
            padded_x = x[:self.padsz]

        return padded_x.long(), y
